function [EvalResult,Info] = sensitivityEvaluationMoonRoverNMSS(p)
%SENSITIVITYEVALUATIONMOONROVERNMSS
%
% Solve a design exploration problem for the MoonRoverNMSS model.
%
% The function returns model results, EvalResult,
% and model evaluation information, Info.
%
% The input argument, p, defines the model parameters to vary,
% if omitted the parameters specified in the function body are varied.
%
% Modify the function to include or exclude new design requirements, or
% to change the evaluation options.
%
% Auto-generated by SSATOOL on 14-May-2026 21:05:38.
%

%% Open the model.
open_system('MoonRoverNMSS')

%% Specify Model Parameters to Vary
%
if nargin < 1 || isempty(p)
    p = sdo.getParameterFromModel('MoonRoverNMSS',{'test_bat_AH','test_pcm_mass'});
    p(1).Value = 50.5;
    p(1).Minimum = 1;
    p(1).Maximum = 100;
    p(2).Value = 2.55;
    p(2).Minimum = 0.1;
    p(2).Maximum = 5;
end
ParamValues = getData('ParamSet');

%% Specify Design Requirements
%
% Specify design requirements to satisfy during optimization.
Requirements = struct;
Requirements.total_regolit_mass = sdo.requirements.SignalProperty(...
    'Function', @max, ...
    'Type', 'max');
Requirements.rover_dry_mass = sdo.requirements.SignalProperty(...
    'Function', @(ts)sdo.requirements.signalPropertyAlgs(ts,'final'), ...
    'Type', 'min');
Requirements.max_temp_bound = sdo.requirements.SignalBound(...
    'BoundMagnitudes', [323 323], ...
    'BoundTimes', [0 950400]);
Requirements.min_temp_bound = sdo.requirements.SignalBound(...
    'BoundMagnitudes', [253 253], ...
    'BoundTimes', [0 950400], ...
    'Type', '>=');
Requirements.min_soc_bound = sdo.requirements.SignalBound(...
    'BoundMagnitudes', [0 0], ...
    'BoundTimes', [0 950400], ...
    'Type', '>=');
Requirements.max_soc_bound = sdo.requirements.SignalBound(...
    'BoundMagnitudes', [1.01 1.01], ...
    'BoundTimes', [0 950400]);

%% Simulation Definition
%
% Specify model signals to log during model simulation.
Simulator = sdo.SimulationTest('MoonRoverNMSS');

Sig_Info = Simulink.SimulationData.SignalLoggingInfo;
Sig_Info.BlockPath = 'MoonRoverNMSS/Core/PS-Simulink Converter';
Sig_Info.LoggingInfo.LoggingName = 'Sig';
Sig_Info.LoggingInfo.NameMode = 1;

Sig_1_Info = Simulink.SimulationData.SignalLoggingInfo;
Sig_1_Info.BlockPath = 'MoonRoverNMSS/Core/Electrical System/PS-Simulink Converter1';
Sig_1_Info.LoggingInfo.LoggingName = 'Sig_1';
Sig_1_Info.LoggingInfo.NameMode = 1;

Sig_2_Info = Simulink.SimulationData.SignalLoggingInfo;
Sig_2_Info.BlockPath = 'MoonRoverNMSS/Core/Electrical System/Motor/kg//s1';
Sig_2_Info.LoggingInfo.LoggingName = 'Sig_2';
Sig_2_Info.LoggingInfo.NameMode = 1;

Sig_3_Info = Simulink.SimulationData.SignalLoggingInfo;
Sig_3_Info.BlockPath = 'MoonRoverNMSS/Core/Electrical System/Motor/Add2';
Sig_3_Info.LoggingInfo.LoggingName = 'Sig_3';
Sig_3_Info.LoggingInfo.NameMode = 1;

Simulator.LoggingInfo.Signals = [...
    Sig_Info; ...
    Sig_1_Info; ...
    Sig_2_Info; ...
    Sig_3_Info];

%% Configure setup and restoration of simulator
%

% Setup simulator
Simulator = setup(Simulator, 'FastRestart', 'off');

% Add Cleanup tasks to restore any changes after completion/termination.
% Use an anonymous function with no arguments that calls the restore method.
SimulatorCleanup = onCleanup(@() restore(Simulator));

%% Create Evaluation Objective Function
%
% Create a function that is called for each combination of parameters
% being varied, to compute the cost.
%
% Use an anonymous function with one argument that calls MoonRoverNMSS_evalFcn.
evalfcn = @(P) MoonRoverNMSS_evalFcn(P,Simulator,Requirements);

%% Evaluation Options
%
% Specify evaluation options.
Options = sdo.EvaluateOptions;
Options.EvaluatedModel = Simulator;
Options.UseParallel = 1;
Options.ParallelPathDependencies = getData('Options_ParallelPathDependencies');
Options.ParallelFileDependencies = getData('Options_ParallelFileDependencies');
Options.ParallelFileDependencies{end+1} = mfilename('fullpath');

%% Evaluate the Model
%
% Call sdo.evaluate with the objective function handle, parameters to
% vary, parameter values, and options.
[EvalResult,Info] = sdo.evaluate(evalfcn,p,ParamValues,Options);
end

function Vals = MoonRoverNMSS_evalFcn(P,Simulator,Requirements)
%MOONROVERNMSS_EVALFCN
%
% Function called at each iteration of the evaluation problem.
%
% The function is called with a set of parameter values, P, and returns
% the evaluated cost, Vals.
%
% See the sdoExampleCostFunction function and sdo.evaluate for a more
% detailed description of the function signature.
%

%% Model Evaluation

% Simulate the model.
Simulator.Parameters = P;
Simulator = sim(Simulator);

% Retrieve logged signal data.
SimLog = find(Simulator.LoggedData,get_param('MoonRoverNMSS','SignalLoggingName'));
Sig_Log = find(SimLog,'Sig');
Sig_1_Log = find(SimLog,'Sig_1');
Sig_2_Log = find(SimLog,'Sig_2');
Sig_3_Log = find(SimLog,'Sig_3');

% Evaluate the design requirements.
Vals.total_regolit_mass = evalRequirement(Requirements.total_regolit_mass,Sig_2_Log.Values);
Vals.rover_dry_mass = evalRequirement(Requirements.rover_dry_mass,Sig_3_Log.Values);
Vals.max_temp_bound = evalRequirement(Requirements.max_temp_bound,Sig_Log.Values);
Vals.min_temp_bound = evalRequirement(Requirements.min_temp_bound,Sig_Log.Values);
Vals.min_soc_bound = evalRequirement(Requirements.min_soc_bound,Sig_1_Log.Values);
Vals.max_soc_bound = evalRequirement(Requirements.max_soc_bound,Sig_1_Log.Values);

% Negate the maximized requirements to get true value.
Vals.total_regolit_mass = -Vals.total_regolit_mass;

% Compress requirement outputs by taking maximum value.
Vals.total_regolit_mass = max(Vals.total_regolit_mass(:));
Vals.rover_dry_mass = max(Vals.rover_dry_mass(:));
Vals.max_temp_bound = max(Vals.max_temp_bound(:));
Vals.min_temp_bound = max(Vals.min_temp_bound(:));
Vals.min_soc_bound = max(Vals.min_soc_bound(:));
Vals.max_soc_bound = max(Vals.max_soc_bound(:));
end

